      Node three2(3);
      Node three3(3);
      Node four(4);
      Node five(5);
      Node six(6);
      bindNodes(&one, &two);
      bindNodes(&two, &three);
      bindNodes(&three, &four);
      bindNodes(&four, &five);
      linkedList.head = &one;
      linkedList.tail = &five;

